-- Verifikasi: realisasi sistem per bidang (bandingkan dengan total CSV = 15825138749):
SELECT b.nama AS bidang,
  (SELECT COALESCE(SUM(d.nominal),0) FROM public.disbursements d JOIN public.pengajuan p ON p.id=d.pengajuan_id WHERE p.bidang_id=b.id) AS realisasi_sistem
FROM public.bidang b ORDER BY b.nama;